__XenMaterialStandalonePreview=(()=>{
  let active=null;
  function stop(){
    const old=active;active=null;if(!old)return;
    try{old.audio.pause();old.audio.onended=null;old.audio.onerror=null;old.audio.removeAttribute?.('src');old.audio.load?.();}catch{}
    try{URL.revokeObjectURL(old.url)}catch{}
  }
  async function toggleById(id){
    if(active?.id===id){stop();return 'stopped';}
    stop();
    const entry=bs().entries.find(item=>item.id===id);
    const blob=entry?.blob;
    if(!blob||typeof blob.size!=='number'||blob.size<=0)return 'unavailable';
    const url=URL.createObjectURL(blob),audio=new Audio();
    const session={id,url,audio};active=session;
    audio.preload='auto';audio.src=url;audio.loop=false;audio.volume=.72;
    audio.onended=()=>{if(active===session)stop();};
    audio.onerror=()=>{if(active===session)stop();};
    try{await audio.play();return active===session?'playing':'stopped';}
    catch(error){if(active===session)stop();throw error;}
  }
  return Object.freeze({toggleById,stop,activeId:()=>active?.id??null});
})();
